pub fn TRKPostInterruptEvent<'a>(ctx: &'a Ctx) {
    let __frame = ctx.stack_frame(0x18);
    let event: NubEvent<'a> = frame_at(ctx, &__frame, 0x4);
    let inst: Val<'a, u32> = frame_at(ctx, &__frame, 0x0);
    let mut eventType: i32 = 0;
    if (fns::gTRKState(ctx).inputActivated() != 0) {
        fns::gTRKState(ctx).set_inputActivated(0_i32);
        return;
    }
    's1: {
        let __case = match (((fns::gTRKCPUState(ctx).Extended1().exceptionID()
            & (0xffff_i32 as u32)) as u16) as i32)
        {
            0x700_i32 => 0,
            0xd00_i32 => 0,
            _ => 1,
        };
        if __case <= 0 {
            let _ = statics::MetroTRK__targimpl::TRKTargetReadInstruction(
                ctx,
                Handle::cast::<Addr<'a>>(inst),
                fns::gTRKCPUState(ctx).Default().PC(),
            );
            if inst.get() == (0xfe00000_i32 as u32) {
                eventType = (enums::kSupportEvent as i32);
            } else {
                eventType = (enums::kBreakpointEvent as i32);
            }
            break 's1;
        }
        if __case <= 1 {
            eventType = (enums::kExceptionEvent as i32);
            break 's1;
        }
    }
    fns::TRKConstructEvent(ctx, event, eventType);
    let _ = fns::TRKPostEvent(ctx, event);
}

